int target = 8;
```
The function should return:
```java
[[1, 1, 6], [1, 2, 5], [1, 7], [2, 6]]
```

### Solution:
```java
import java.util.*;

public class CombinationSum2 {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        List<List<Integer>> result = new ArrayList<>();
        Arrays.sort(candidates);
        backtrack(result, new ArrayList<>(), candidates, target, 0);
        return result;
    }

    private void backtrack(List<List<Integer>> result, List<Integer> tempList, int[] candidates, int remain, int start) {
        if (remain < 0) return;
        else if (remain == 0) result.add(new ArrayList<>(tempList));
        else {
            for (int i = start; i < candidates.length; i++) {
                if (i > start && candidates[i] == candidates[i - 1]) continue; // skip duplicates
                tempList.add(candidates[i]);
                backtrack(result, tempList, candidates, remain - candidates[i], i + 1);
                tempList.remove(tempList.size() - 1);
            }
        }
    }
}
```

### Problem:
You are given a code snippet that represents a partial implementation of a function to generate unique permutations of a given set of integers. Your task is to complete the implementation of the `permuteUniqueHelper` function to generate all unique permutations of the input integers and return the results.

The `permuteUniqueHelper` function takes the following parameters:
- `results`: A reference to a vector of vectors of integers where the unique permutations will be stored.
- `path`: A vector of integers representing the current permutation path being constructed.
- `startIndex`: An integer representing the index to start permutation from.

You need to complete the `permuteUniqueHelper` function to generate all unique permutations of the input integers and store them in the `results` vector.

Your task is to complete the implementation of the `permuteUniqueHelper` function to generate all unique permutations of the input integers and return the results.

Complete the `permuteUniqueHelper` function to generate all unique permutations of the input integers and store them in the `results` vector.

```cpp
#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> permuteUnique(std::vector<int>& nums) {
        std::vector<std::vector<int>> results;
        std::sort(nums.begin(), nums.end());
        permuteUniqueHelper(results, nums, 0);
        return results;
    }
private:
    void permuteUniqueHelper(std::vector<std::vector<int>> &results, std::vector<int> path, int startIndex) {
        if (startIndex == path.size()) {
            results.push_back(path);
        } else {
            std::vector<int> uniqueCheck;
            for (int i = startIndex; i < path.size(); i++) {
                if (std::find(uniqueCheck.begin(), uniqueCheck.end(), path[i]) != uniqueCheck.end()) {
                    continue;
                }
                uniqueCheck.push_back(path[i]);
                std::swap(path[startIndex], path[i]);
                permuteUniqueHelper(results, path, startIndex + 1);
                std::swap(path[startIndex], path[i]);
            }
        }
    }
};
```

