### Solution:
```cpp
#include <vector>

bool isValid(std::vector<std::vector<int>>& puzzle, int row, int col, int num) {
    for (int i = 0; i < 9; i++) {
        if (puzzle[row][i] == num || puzzle[i][col] == num || puzzle[3 * (row / 3) + i / 3][3 * (col / 3) + i % 3] == num) {
            return false;
        }
    }
    return true;
}

bool solveSudokuUtil(std::vector<std::vector<int>>& puzzle, int row, int col) {
    if (row == 9) {
        return true;
    }
    if (col == 9) {
        return solveSudokuUtil(puzzle, row + 1, 0);
    }
    if (puzzle[row][col] != 0) {
        return solveSudokuUtil(puzzle, row, col + 1);
    }
    for (int num = 1; num <= 9; num++) {
        if (isValid(puzzle, row, col, num)) {
            puzzle[row][col] = num;
            if (solveSudokuUtil(puzzle, row, col + 1)) {
                return true;
            }
            puzzle[row][col] = 0;
        }
    }
    return false;
}

void solveSudoku(std::vector<std::vector<int>>& puzzle) {
    solveSudokuUtil(puzzle, 0, 0);
}
```
